#include <bits/stdc++.h>
using namespace std;
struct Node{int child[256];int sym;Node(){memset(child,0,sizeof child);sym=-1;}};
int main(int argc,char**argv){ifstream f("/inputs/python-source.py",ios::binary);string s((istreambuf_iterator<char>(f)),{});ifstream d(argc>1?argv[1]:"/work/grammar/dict.bin",ios::binary);vector<string> dict;while(1){unsigned char len;d.read((char*)&len,1);if(!d)break;string w(len,'\0');d.read(w.data(),len);dict.push_back(w);}vector<Node> trie(1);trie.reserve(1000000);for(int code=0;code<(int)dict.size();code++){int p=0;for(uint8_t c:dict[code]){if(!trie[p].child[c]){int ix=trie.size();trie.emplace_back();trie[p].child[c]=ix;}p=trie[p].child[c];}trie[p].sym=code;}fprintf(stderr,"trie %zu memory%zu\n",trie.size(),trie.size()*sizeof(Node));vector<uint32_t> cost(s.size()+1);vector<uint16_t> token(s.size());vector<uint8_t> len(s.size());
for(size_t p=s.size();p-->0;){uint32_t best=1+cost[p+1];int id=(uint8_t)s[p],sz=1;int node=0;for(size_t k=p;k<s.size() && k<p+64;k++){node=trie[node].child[(uint8_t)s[k]];if(!node)break;if(trie[node].sym>=0 && 1+cost[k+1]<=best){best=1+cost[k+1];id=trie[node].sym;sz=k+1-p;}}cost[p]=best;token[p]=id;len[p]=sz;if((p%10000000)==0)fprintf(stderr,"at %zu tokens%u\n",p,best);}
ofstream out(argc>2?argv[2]:"/work/grammar/tokens.bin",ios::binary);vector<size_t> ct(256);for(size_t p=0;p<s.size();){uint16_t id=token[p];out.write((char*)&id,2);ct[len[p]]++;p+=len[p];}printf("count %u total%zu\n",cost[0],cost[0]*size_t(2)+667739);for(int i=1;i<256;i++)if(ct[i])printf("len%u count%zu\n",i,ct[i]);}
